import SendbirdChat from '@sendbird/chat';
import { GroupChannelModule } from '@sendbird/chat/groupChannel';

const sb = SendbirdChat.init({
  appId: process.env.NEXT_PUBLIC_SENDBIRD_APP_ID!,
  modules: [new GroupChannelModule()],
});

// accessToken generated server-side
await sb.connect('user-123', accessToken);

console.log('Connected as:', sb.currentUser?.nickname);

// Create a group channel
const { groupChannel } = sb.groupChannel;
const channel = await groupChannel.createChannel({
  invitedUserIds: ['user-123', 'user-456'],
  isDistinct: true, // Reuse same channel for same pair of users
  name: 'Support Chat',
});
